<?php
require __DIR__ . '/../app/bootstrap.php';
require __DIR__ . '/../app/license_renewal.php';
$u=require_role(['owner','admin','manager','staff']);$msg=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$r=skynoc_renew_license((int)($_POST['license_id']??0),(int)($_POST['months']??0),(float)($_POST['amount']??0),(int)$u['id']);$msg='Renewal completed for '.$r['license_key'].' until '.$r['expires_at'].'.';}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$db->query("SELECT l.id,l.license_key,l.domain,l.status,l.expires_at,r.name reseller_name,r.email reseller_email FROM licenses l LEFT JOIN resellers r ON r.id=l.reseller_id WHERE l.reseller_id IS NOT NULL AND l.status IN ('active','expired') ORDER BY l.expires_at ASC LIMIT 100")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>License Renewals — SkyNoc</title><link rel="stylesheet" href="/admin-page-ui.css"><style>.wrap{max-width:1100px;margin:25px auto;padding:0 16px}.hero,.card{background:#fff;border:1px solid #e4e7ec;border-radius:18px;padding:20px;margin-bottom:14px}.hero{background:linear-gradient(135deg,#111827,#1d4ed8);color:#fff}.grid{display:grid;grid-template-columns:1.2fr 1fr;gap:18px}.meta{font-size:12px;color:#667085;line-height:1.8}.formgrid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}.btn{border:0;border-radius:10px;padding:10px 14px;font-weight:800;background:#465fff;color:#fff}.alert{padding:12px;border-radius:12px;margin-bottom:14px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}@media(max-width:700px){.grid,.formgrid{grid-template-columns:1fr}}</style></head><body><div class="top"><strong>SkyNoc / Admin</strong><span><?=e($u['name'])?> · <a href="/admin">Dashboard</a></span></div><div class="wrap"><div class="hero"><h1>License Renewals</h1><p>Renew active or expired reseller licenses and notify Telegram + Discord automatically.</p></div><?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert err"><?=e($error)?></div><?php endif;?><?php foreach($rows as $l):?><div class="card"><div class="grid"><div><strong>#<?=e((string)$l['id'])?> — <code><?=e($l['license_key'])?></code></strong><div class="meta">Reseller: <?=e((string)$l['reseller_name'])?><br>Domain: <?=e((string)($l['domain']?:'-'))?><br>Status: <?=e(strtoupper($l['status']))?><br>Expires: <?=e((string)($l['expires_at']?:'-'))?></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="license_id" value="<?=e((string)$l['id'])?>"><div class="formgrid"><select name="months"><option value="1">1 Month</option><option value="12">12 Months</option></select><input name="amount" type="number" step="0.01" min="0.01" placeholder="Amount USD" required><button class="btn">Renew</button></div></form></div></div><?php endforeach;?></div></body></html>
